Variable Importance Plots

# Calculate permutation importance
perm_importance &lt;- function(fitted_model, data) {
  predictors &lt;- setdiff(names(data), "bike_count")

  baseline &lt;- predict(fitted_model, new_data = data) |&gt;
    bind_cols(data |&gt; select(bike_count)) |&gt;
    rmse(truth = bike_count, estimate = .pred) |&gt;
    pull(.estimate)

  importance &lt;- purrr::map_dfr(predictors, function(var) {
    set.seed(558)
    shuffled_data &lt;- data
    shuffled_data[[var]] &lt;- sample(shuffled_data[[var]])

    shuffled_rmse &lt;- predict(
      fitted_model,
      new_data = shuffled_data
    ) |&gt;
      bind_cols(data |&gt; select(bike_count)) |&gt;
      rmse(truth = bike_count, estimate = .pred) |&gt;
      pull(.estimate)

    tibble(
      variable = var,
      importance = shuffled_rmse - baseline
    )
  })

  importance |&gt; arrange(desc(importance))
}

# Bagged tree variable importance
bag_importance &lt;- perm_importance(
  final_bag_fit,
  bike_train
)

# Random forest variable importance
rf_importance &lt;- perm_importance(
  final_rf_fit,
  bike_train
)

# Plot bagged tree importance
ggplot(
  bag_importance,
  aes(x = reorder(variable, importance), y = importance)
) +
  geom_col() +
  coord_flip() +
  labs(
    title = "Bagged Tree Variable Importance",
    x = "Predictor",
    y = "Increase in RMSE"
  )







# Plot random forest importance
ggplot(
  rf_importance,
  aes(x = reorder(variable, importance), y = importance)
) + 
  geom_col() +
  coord_flip() +
  labs(
    title = "Random Forest Variable Importance",
    x = "Predictor",
    y = "Increase in RMSE"
  )

#Recipe 1
recipe1 &lt;- recipe(sum_bkcnt ~., data = bike_train) |&gt;
            step_date(date, features = "dow", keep_original_cols = FALSE) |&gt;
            step_mutate(
              day_type = factor(
                if_else(
                  date_dow %in% c("Sat", "Sun"),
                  "Weekend", "Weekday"
                )
              )
            ) |&gt;
            step_rm(day_type) |&gt;
            step_normalize(all_numeric_predictors()) |&gt;
            step_dummy(all_nominal_predictors())

#Recipe 2
recipe2 &lt;- recipe1 |&gt;  
  step_interact( terms = ~ starts_with("seasons_"):starts_with("holiday_") +
                   starts_with("seasons_"):mean_tmp + mean_tmp:sum_rf)

#Recipe3
recipe3 &lt;- recipe2 |&gt;
  step_mutate(
    tmp_sq = mean_tmp^2,
    humid_sq = mean_humid^2
  )

